import{R as e,e as o,f as n,U as r}from"./chunks/framework.ywem4qy5.js";const p=JSON.parse('{"title":"Trello","description":"","frontmatter":{},"headers":[],"relativePath":"integrations/miscellaneous/trello.md","filePath":"integrations/miscellaneous/trello.md","lastUpdated":1775908585000}'),l={name:"integrations/miscellaneous/trello.md"};function i(a,t,s,h,g,c){return o(),n("div",null,[...t[0]||(t[0]=[r('<h1 id="trello" tabindex="-1">Trello <a class="header-anchor" href="#trello" aria-label="Permalink to &quot;Trello&quot;">​</a></h1><p>Follow the below steps to connect to the Trello API.</p><h3 id="step-1-create-the-integration" tabindex="-1">Step 1. Create the Integration <a class="header-anchor" href="#step-1-create-the-integration" aria-label="Permalink to &quot;Step 1. Create the Integration&quot;">​</a></h3><ol><li>Navigate to <strong>Formie</strong> → <strong>Settings</strong> → <strong>Miscellaneous</strong>.</li><li>Click the <strong>New Integration</strong> button.</li><li>Select Trello as the <strong>Integration Provider</strong>.</li></ol><h3 id="step-2-connect-to-the-trello-api" tabindex="-1">Step 2. Connect to the Trello API <a class="header-anchor" href="#step-2-connect-to-the-trello-api" aria-label="Permalink to &quot;Step 2. Connect to the Trello API&quot;">​</a></h3><ol><li>Go to the <a href="https://trello.com/app-key" target="_blank">Trello API Key</a> page.</li><li>Under the <strong>Developer API Keys</strong> heading, copy the <strong>Key</strong> value into the <strong>Client ID</strong> field in Formie.</li><li>Under the <strong>Allowed Origins</strong> heading, enter the value from the <strong>Redirect URI</strong> field in Formie into the text field under <strong>New Allowed Origin</strong> and hit <strong>Submit</strong>.</li><li>Under the <strong>OAuth</strong> heading, copy the <strong>Secret</strong> value into the <strong>Client Secret</strong> field in Formie.</li></ol><h3 id="step-3-test-connection" tabindex="-1">Step 3. Test Connection <a class="header-anchor" href="#step-3-test-connection" aria-label="Permalink to &quot;Step 3. Test Connection&quot;">​</a></h3><ol><li>Save this integration.</li><li>Click on the <strong>Connect</strong> button in the right-hand sidebar.</li><li>You‘ll be redirected to Trello, where you must approve Formie to access your Trello account.</li></ol><h3 id="step-4-form-setting" tabindex="-1">Step 4. Form Setting <a class="header-anchor" href="#step-4-form-setting" aria-label="Permalink to &quot;Step 4. Form Setting&quot;">​</a></h3><ol><li>Go to the form you want to enable this integration on.</li><li>Click the <strong>Integrations</strong> tab.</li><li>In the left-hand sidebar, select the name you gave the integration.</li><li>Enable the integration and fill out all required fields.</li><li>Click <strong>Save</strong> to save the form.</li></ol>',10)])])}const u=e(l,[["render",i]]);export{p as __pageData,u as default};
